import math

def count_divisors(n):
    """Calculates the number of positive divisors of n."""
    if n == 0:
        return 0
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def check_condition(k):
    """Checks if d(2k^3) == 2k."""
    n = 2 * (k**3)
    d_n = count_divisors(n)
    target = 2 * k
    return d_n == target

solutions = []
for k in range(1, 31):
    if check_condition(k):
        solutions.append(k)

print(f"Solutions found up to k=30: {solutions}")
# Double check k=3 explicitly
k3_check = check_condition(3)
print(f"k=3 satisfies condition? {k3_check}")

import math

def count_divisors(n):
    if n <= 0:
        return 0
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

# Test k from 31 to 50
solutions = []
for k in range(31, 51):
    N = 2 * (k**3)
    divisors = count_divisors(N)
    target = 2 * k

    if divisors == target:
        solutions.append(k)

    # Optional: Print intermediate results for verification
